CREATE TABLE public.care_ai_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), farmer_id uuid NOT NULL REFERENCES public.profiles(id), livestock_id uuid NOT NULL, symptoms text NOT NULL CHECK(length(btrim(symptoms)) BETWEEN 1 AND 3000), language text NOT NULL CHECK(language IN('ha','en')), consent_at timestamptz NOT NULL DEFAULT now(), response text, status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','completed','failed','denied')), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(livestock_id,farmer_id) REFERENCES public.livestock(id,owner_id)); GRANT SELECT ON public.care_ai_requests TO authenticated; GRANT ALL ON public.care_ai_requests TO service_role; ALTER TABLE public.care_ai_requests ENABLE ROW LEVEL SECURITY; CREATE POLICY "Farmer private AI history" ON public.care_ai_requests FOR SELECT TO authenticated USING(farmer_id=auth.uid() AND public.has_role(auth.uid(),'farmer'));
CREATE TABLE public.care_ai_service_state(id text PRIMARY KEY CHECK(id='gateway'), paused boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.care_ai_service_state TO service_role; ALTER TABLE public.care_ai_service_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.care_video_rooms(appointment_id uuid PRIMARY KEY REFERENCES public.care_appointments(id), room_name text NOT NULL UNIQUE, room_url text NOT NULL, expires_at timestamptz NOT NULL); GRANT ALL ON public.care_video_rooms TO service_role; ALTER TABLE public.care_video_rooms ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.care_reschedule(_id uuid,_slot uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.care_appointments; s public.care_slots; nid uuid; BEGIN SELECT * INTO a FROM public.care_appointments WHERE id=_id FOR UPDATE; IF a.farmer_id IS DISTINCT FROM auth.uid() OR NOT public.has_role(auth.uid(),'farmer') OR a.status NOT IN('requested','confirmed') THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; SELECT * INTO s FROM public.care_slots WHERE id=_slot AND vet_id=a.vet_id; IF s.id IS NULL THEN RAISE EXCEPTION 'invalid_slot'; END IF; UPDATE public.care_appointments SET status='cancelled',updated_at=now() WHERE id=_id; nid=public.care_book(_slot,a.livestock_id,a.reason); INSERT INTO public.care_audit(actor_id,farmer_id,vet_id,livestock_id,action,record_id) VALUES(auth.uid(),a.farmer_id,a.vet_id,a.livestock_id,'appointment_rescheduled',a.id); INSERT INTO public.care_notifications(recipient_id,appointment_id,kind,dedupe_key) VALUES(a.vet_id,a.id,'appointment_cancelled',a.id::text||':cancelled') ON CONFLICT DO NOTHING; RETURN nid; END $$; REVOKE ALL ON FUNCTION public.care_reschedule(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_reschedule(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_notification_read() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.read_at=now(); RETURN NEW; END $$; CREATE TRIGGER care_notification_read BEFORE UPDATE ON public.care_notifications FOR EACH ROW EXECUTE FUNCTION public.care_notification_read();
CREATE OR REPLACE FUNCTION public.care_validate_slot_publication() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.published THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.vet_id::text,0)); IF EXISTS(SELECT 1 FROM public.care_slots s WHERE s.id<>NEW.id AND s.vet_id=NEW.vet_id AND s.published AND s.starts_at<NEW.ends_at AND s.ends_at>NEW.starts_at) THEN RAISE EXCEPTION 'slot_conflict' USING ERRCODE='23505'; END IF; END IF; RETURN NEW; END $$; CREATE TRIGGER care_validate_slot_publication BEFORE UPDATE ON public.care_slots FOR EACH ROW EXECUTE FUNCTION public.care_validate_slot_publication();
CREATE OR REPLACE FUNCTION public.care_clinical_confirmation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.author_id IS DISTINCT FROM auth.uid() OR NOT public.care_clinical_author(NEW.appointment_id) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; PERFORM 1 FROM public.care_shares s JOIN public.care_appointments a ON a.id=NEW.appointment_id WHERE s.farmer_id=a.farmer_id AND s.vet_id=a.vet_id AND s.livestock_id=a.livestock_id FOR SHARE OF s; IF NOT public.care_clinical_author(NEW.appointment_id) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; RETURN NEW; END $$; CREATE TRIGGER care_note_authorization BEFORE INSERT ON public.care_consultations FOR EACH ROW EXECUTE FUNCTION public.care_clinical_confirmation(); CREATE TRIGGER care_prescription_authorization BEFORE INSERT ON public.care_prescriptions FOR EACH ROW EXECUTE FUNCTION public.care_clinical_confirmation();
CREATE OR REPLACE FUNCTION public.care_required_confirmation(_confirmed boolean) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ BEGIN IF _confirmed IS DISTINCT FROM true THEN RAISE EXCEPTION 'confirmation_required' USING ERRCODE='42501'; END IF; RETURN true; END $$; REVOKE ALL ON FUNCTION public.care_required_confirmation(boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_required_confirmation(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.care_publish_prescription(_appointment uuid,_consultation uuid,_medicine text,_dose text,_route text,_frequency text,_duration text,_instructions text,_withdrawal text,_confirmed boolean,_supersedes uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.care_required_confirmation(_confirmed); RETURN public.care_issue_prescription(_appointment,_consultation,_medicine,_dose,_route,_frequency,_duration,_instructions,_withdrawal,true,_supersedes); END $$; REVOKE ALL ON FUNCTION public.care_publish_prescription(uuid,uuid,text,text,text,text,text,text,text,boolean,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_publish_prescription(uuid,uuid,text,text,text,text,text,text,text,boolean,uuid) TO authenticated; REVOKE EXECUTE ON FUNCTION public.care_issue_prescription(uuid,uuid,text,text,text,text,text,text,text,boolean,uuid) FROM authenticated;
CREATE OR REPLACE FUNCTION public.care_review_report(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin')) THEN RAISE EXCEPTION 'forbidden' USING ERRCODE='42501'; END IF; UPDATE public.care_reports SET status='reviewed' WHERE id=_id; END $$; REVOKE ALL ON FUNCTION public.care_review_report(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.care_review_report(uuid) TO authenticated;
CREATE POLICY "Admin report metadata only" ON public.care_reports FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'super_admin'));